local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[403207]=b({e[17044],403207,4,96,191,"「わ～っ、今日の雪、ふわふわ。踏んでみると、まるで刈った羊さんの毛の山みたい！\nオオカミさん、一緒に雪だるま作ろ？ リサリサは、かわいい雪の羊さんを作るね！\nオオカミさんは、かっこよくて、いつもリサリサを守ってくれる、優しいオオカミさんを作って！ ぽややんは、指導役をお願い！\nリサリサと、オオカミさん、それにぽややんで、今日は世界でいっちばん幸せなクリスマス牧場を作っちゃおう！」",200032,2,"deco/character/ailisha_sd",false,false,false,false,false,false,false,"",0,false,false,false,false,false,false,false,false,false,false,false,false,"ailisha_sd"},h)g[403301]=b({e[17044],403301,false,97,192,false,200033,false,"deco/character/siqiqiansuili",302002,60,false,false,false,false,124,"0.949999988079071",0,false,false,false,false,false,false,false,false,false,false,false,false,"siqiqiansuili"},h)g[403302]=b({e[12044],403302,1,4,193,"「君の影響で、こうしてゆったりとした午後を過ごしているけれど……良いんだか悪いんだか。\nどうやら私も『堕ちた』ようね、ふふっ。」",200033,1,"deco/character/siqiqiansuili_0",302002,60,1,0,false,false,false,false,false,false,false,false,false,false,false,false,"siqiqiansuili_0"},h)g[403303]=b({e[17044],403303,11,56,194,"「早くしないと置いてくわよ！　……二人きりのお出かけなのに、仕事のことを優先しちゃうなんて、悪いとは思ってるわ。でもね、あれは結構な特ダネなのよ！　終わったらどこにでも付き合うから、今は許して！　ね？」",200033,2,"deco/character/siqiqiansuili_YY",false,false,1,1,false,false,false,"1",0,false,false,false,false,false,false,false,false,false,false,false,false,"siqiqiansuili_yy"},h)g[403304]=b({e[17044],403304,2,14,195,"「さ、こっちに座って。一緒に飲みながら、日光浴を楽しみましょ。そうだ、日焼け止めを塗ってあげるわ。私の塗りの技術、しっかり肌で感じてね。後でじっくりとインタビューさせてもらうから。」",200033,2,"deco/character/siqiqiansuili_YZ",false,false,false,false,false,false,false,"1",0,1,3858,5000,1655,3999,13333,6666,6666,13366,15000,8000,13333,"siqiqiansuili_xr"},h)g[403305]=b({e[17044],403305,13,45,196,"「噂の真偽に対する探求心は、ジャーナリストの性のようなものね。\nこの『みかんの湯』のうるおい効果がどれほどのものか……ふふっ、一緒に検証しましょうか。」",200033,2,"deco/character/siqiqiansuili_wq",false,false,1,1,false,false,false,"1",0,false,false,false,false,false,false,false,false,false,false,false,false,"siqiqiansuili_wq"},h)g[4034